        "Tilbagevisende udsagnsord: ich verlaufe mich, er verläuft sich, verlief sich, hat sich verlaufen. I førnutid bruges haben. Ordet bruges som regel med en stedsangivelse: im Wald, in der Stadt, in den Bergen.",
